import sqlite3,pathlib,datetime
root=pathlib.Path(__file__).resolve().parent;db=sqlite3.connect(":memory:");db.executescript((root/"server-d1-init.sql").read_text(encoding="utf-8"));now=datetime.datetime.now(datetime.timezone.utc).isoformat();exp=(datetime.datetime.now(datetime.timezone.utc)+datetime.timedelta(days=180)).isoformat();db.execute("INSERT INTO guest_sessions(id,token_hash,created_at,last_seen_at,expires_at) VALUES(?,?,?,?,?)",("g","h",now,now,exp));db.execute("""INSERT INTO profiles(id,guest_session_id,display_name,calendar,lunar_leap_month,birth_year,birth_month,birth_day,hour_unknown,timezone,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",("p","g","진아","양력",0,1991,11,23,1,"Asia/Seoul",now,now));db.execute("INSERT INTO conversations(id,guest_session_id,title,created_at,updated_at) VALUES(?,?,?,?,?)",("c","g","상담",now,now));db.execute("INSERT INTO messages(id,conversation_id,role,content,request_id,created_at) VALUES(?,?,?,?,?,?)",("m","c","user","질문","req1",now));assert db.execute("SELECT display_name FROM profiles WHERE id='p'").fetchone()[0]=="진아";assert db.execute("SELECT content FROM messages WHERE conversation_id='c'").fetchone()[0]=="질문";db.execute("UPDATE profiles SET deleted_at=?,updated_at=? WHERE id='p' AND guest_session_id='g'",(now,now));db.execute("UPDATE conversations SET deleted_at=?,updated_at=? WHERE id='c' AND guest_session_id='g'",(now,now));assert db.execute("SELECT deleted_at FROM profiles WHERE id='p'").fetchone()[0] is not None;print("Data CRUD SQLite smoke: ALL PASS")
